      /**
       * 插入文档
       */
      async insertDocuments(documents) {
        if (isTenantIsolationRequired() && documents.some((document) => !isServerDerivedScope(document.metadata))) {
          throw new Error("Milvus insertion requires authenticated server-derived document scope.");
        }
        if (!this.isInitialized) {
          await this.initializeCollection();
        }
        const client2 = await this.ensureConnected();
        const collectionName = this.config.collectionName;
        console.log(`[Milvus] Preparing to insert ${documents.length} documents...`);
        const firstDimension = documents[0]?.embedding?.length;
        if (!firstDimension) {
          throw new Error("First document has no embedding or invalid embedding");
        }
        for (let i5 = 0; i5 < documents.length; i5++) {
          const doc = documents[i5];
          if (!doc.embedding || !Array.isArray(doc.embedding)) {
            console.error(`[Milvus] Document ${i5} (id: ${doc.id}) has invalid embedding:`, doc.embedding);
            throw new Error(`Document ${i5} (id: ${doc.id}) has invalid embedding`);
          }
          if (doc.embedding.length !== firstDimension) {
            console.error(`[Milvus] Dimension mismatch at document ${i5}:`, {
              docId: doc.id,
              expected: firstDimension,
              actual: doc.embedding.length
            });
            throw new Error(`Document ${i5} (id: ${doc.id}) has mismatched embedding dimension: expected ${firstDimension}D, got ${doc.embedding.length}D`);
          }
        }
        console.log(`[Milvus] \u2705 All ${documents.length} documents have consistent embedding dimension: ${firstDimension}D`);
        if (isTenantIsolationRequired() && !this.supportsTenantIsolation) {
          throw new Error("Active Milvus collection does not support required tenant isolation fields.");
        }
        const data2 = documents.map((doc) => {
          const base = {
            id: doc.id,
            content: doc.content.substring(0, 65e3),
            // 限制长度
            embedding: doc.embedding,
            source: String(doc.metadata?.source || "unknown").substring(0, 1024),
            metadata_json: JSON.stringify(doc.metadata || {}).substring(0, 65e3),
            created_at: Date.now()
          };
          const orderedFields = this.supportsOrderedContext ? getOrderedDocumentFields(doc.metadata) : {};
          if (!this.supportsTenantIsolation) return { ...base, ...orderedFields };
          return {
            ...base,
            ...orderedFields,
            ...getDocumentSecurityFields(doc.metadata, {
              tenantId: process.env.RAG_DEFAULT_TENANT_ID || "local",
              corpusId: process.env.RAG_DEFAULT_CORPUS_ID || "default",
              trustLevel: "external"
            })
          };
        });
        console.log(`[Milvus] Inserting ${documents.length} documents...`);
        console.log(`[Milvus] Sample document structure:`, {
          id: data2[0].id,
          contentLength: data2[0].content.length,
          embeddingDimension: data2[0].embedding.length,
          source: data2[0].source
        });
        const upsertReq = {
          collection_name: collectionName,
          data: data2
        };
        const result = await client2.upsert(upsertReq);
        if (result.status.error_code !== "Success") {
          throw new Error(`Upsert failed: ${result.status.reason}`);
        }
        const upsertCount = Number(result.upsert_cnt);
        if (!Number.isSafeInteger(upsertCount) || upsertCount !== data2.length) {
          throw new Error(
            `Upsert count mismatch: expected ${data2.length}, received ${result.upsert_cnt}.`
          );
        }
        console.log(`[Milvus] Upserted ${upsertCount} documents`);
        if (this.config.flushOnInsert) {
          console.log(`[Milvus] Flushing data...`);
          await client2.flushSync({ collection_names: [collectionName] });
        }
        if (this.config.reloadAfterInsert) {
          console.log(`[Milvus] Reloading collection to make new data searchable...`);
          try {
            await client2.releaseCollection({ collection_name: collectionName });
            await client2.loadCollection({ collection_name: collectionName });
            console.log(`[Milvus] Collection reloaded successfully`);
          } catch (reloadError) {
            console.warn(`[Milvus] Reload warning (may be OK):`, reloadError);
          }
        }
        return data2.map((d5) => d5.id);
      }
      async probeHybridCollection(input) {
        assertMilvusHybridNotAborted(input.signal);
        const collectionName = safeMilvusIdentifier(input.collectionName, "collectionName");
        const cached2 = this.hybridCapabilityCache.get(collectionName);
        if (cached2 && cached2.expiresAt > Date.now()) {
          return { ...cached2.capability };
        }
        if (cached2) this.hybridCapabilityCache.delete(collectionName);
        let probe = this.hybridCapabilityProbes.get(collectionName);
        if (!probe) {
          probe = this.performHybridCollectionProbe(collectionName);
          this.hybridCapabilityProbes.set(collectionName, probe);
          void probe.then(
            () => this.hybridCapabilityProbes.delete(collectionName),
            () => this.hybridCapabilityProbes.delete(collectionName)
          );
        }
        const capability = await probe;
        assertMilvusHybridNotAborted(input.signal);
        this.hybridCapabilityCache.set(collectionName, {
          expiresAt: Date.now() + MILVUS_HYBRID_CAPABILITY_CACHE_TTL_MS,
          capability: { ...capability }
        });
        return { ...capability };
      }
      async performHybridCollectionProbe(collectionName) {
        try {
          const client2 = await this.ensureConnected();
          const exists = await client2.hasCollection({ collection_name: collectionName });
          if (!exists.value) {
            return {
              nativeHybridSearch: typeof client2.hybridSearch === "function",
              bm25Function: false,
              schemaCompatible: false,
              provider: getMilvusProvider(),
              reason: "collection_missing"
            };
          }
          const description = await client2.describeCollection({ collection_name: collectionName });
          const fields = description.schema?.fields ?? [];
          const fieldNames = new Set(fields.map((field) => field.name));
          const requiredScalars = [
            "id",
            "content",
            "source",
            "metadata_json",
            "tenant_id",
            "corpus_id",
            "document_id",
            "document_version",
            "trust_level",
            "chunk_index",
            "total_chunks"
          ];
          const rawText = fields.find((field) => field.name === "content");
          const dense = fields.find((field) => field.name === "embedding");
          const sparse = fields.find((field) => field.name === "bm25_sparse");
          const functions = [
            ...description.schema?.functions ?? [],
            ...description.functions ?? []
          ];
          const bm25Function = functions.some(
            (fn) => isBm25Function(fn, "content", "bm25_sparse")
          );
          const schemaCompatible = requiredScalars.every((field) => fieldNames.has(field)) && isMilvusFieldType(rawText, import_milvus2_sdk_node2.DataType.VarChar, "VarChar") && isAnalyzerEnabled(rawText) && isMilvusFieldType(dense, import_milvus2_sdk_node2.DataType.FloatVector, "FloatVector") && readMilvusFieldDimension(dense) === this.config.embeddingDimension && isMilvusFieldType(sparse, import_milvus2_sdk_node2.DataType.SparseFloatVector, "SparseFloatVector") && Boolean(sparse?.is_function_output);
          let serverVersion;
          try {
            serverVersion = (await client2.getVersion()).version;
          } catch {
            serverVersion = void 0;
          }
          return {
            nativeHybridSearch: typeof client2.hybridSearch === "function",
            bm25Function,
            schemaCompatible,
            provider: getMilvusProvider(),
            ...serverVersion ? { serverVersion } : {},
            ...!schemaCompatible ? { reason: "shadow_schema_incompatible" } : !bm25Function ? { reason: "bm25_function_missing" } : {}
          };
        } catch {
          return {
            nativeHybridSearch: false,
            bm25Function: false,
            schemaCompatible: false,
            provider: getMilvusProvider(),
            reason: "capability_probe_failed"
          };
        }
      }
      invalidateHybridCapabilityCache(collectionName) {
        this.hybridCapabilityCache.delete(collectionName);
        this.hybridCapabilityProbes.delete(collectionName);
      }
